import pandas as pd,numpy as np
from scipy.optimize import least_squares
from scipy.signal import lfilter
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_fault_op1.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv']
D={f:pd.read_csv(f) for f in files}
dec=10; dt=0.01
def prep(d):
    return dict(V=d.voltage_pu.values[::dec]-d.voltage_pu.values[0],
                th=d.bus_angle_rad.values[::dec]-0,
                Vs=d.voltage_setpoint_pu.values[::dec]-d.voltage_setpoint_pu.values[0],
                P=d.active_power_pu.values[::dec]-d.active_power_pu.values[0],
                Q=d.reactive_power_pu.values[::dec]-d.reactive_power_pu.values[0])
DD={f:prep(D[f]) for f in files}
def tf(num,den,u):
    # den: [1,a1,a2]; num length 3 (b0,b1,b2) (in s^2 form: s^2 numerator etc.) use discrete via bilinear-ish: just lfilter on sampled signal
    return lfilter(num,den,u)
def model_q(p,x):
    a1,a2=p[0],p[1]
    den=[1,a1,a2]
    # discrete Euler-ish: use continuous via bilinear
    from scipy.signal import bilinear
    bq,aq=bilinear(p[2:5],[1,a1,a2],fs=1/dt)
    bV,aV=bilinear(p[5:8],[1,a1,a2],fs=1/dt)
    return lfilter(bq,aq,x['Vs'])+lfilter(bV,aV,x['V'])
def model_p(p,x):
    a1,a2=p[0],p[1]
    from scipy.signal import bilinear
    bV,aV=bilinear(p[2:5],[1,a1,a2],fs=1/dt)
    bt,at=bilinear(p[5:8],[1,a1,a2],fs=1/dt)
    return lfilter(bV,aV,x['V'])+lfilter(bt,at,x['th'])
def res_q(p,fl=files):
    return np.concatenate([model_q(p,DD[f])-DD[f]['Q'] for f in fl])
def res_p(p,fl=files):
    return np.concatenate([model_p(p,DD[f])-DD[f]['P'] for f in fl])
lb=[0.01,0.01,-100,-100,-100,-100,-100,-100]; ub=[100,1000,100,100,100,100,100,100]
best=None
for a1 in [1,5,20]:
  for a2 in [1,10,100]:
    p0=[a1,a2,1,1,1,1,1,1]
    r=least_squares(res_q,p0,bounds=(lb,ub),max_nfev=300)
    if best is None or r.cost<best.cost: best=r
print('Q',np.round(best.x,4), np.sqrt(np.mean(best.fun**2)))
pq=best.x
for f in files: print(f, np.sqrt(np.mean((model_q(pq,DD[f])-DD[f]['Q'])**2)).round(5))
bp=least_squares(res_p,[1,1,1,1,1,1,1,1],bounds=(lb,ub),max_nfev=300)
print('P',np.round(bp.x,4), np.sqrt(np.mean(bp.fun**2)))
for f in files: print(f, np.sqrt(np.mean((model_p(bp.x,DD[f])-DD[f]['P'])**2)).round(5))
np.save('pq.npy',pq); np.save('pp.npy',bp.x)

